"""Baseline: measured outline extruded, holes cut. Generated by baseline_cad.py."""
import cadquery as cq


def build_part(
    thickness=3.0,
    corner1_u=-7.9, corner1_v=-18.65,
    corner2_u=-7.99, corner2_v=-6.52,
    corner3_u=-24.77, corner3_v=-6.68,
    corner4_u=-24.65, corner4_v=18.6,
    corner5_u=24.76, corner5_v=18.58,
    corner6_u=24.5, corner6_v=-6.55,
    corner7_u=7.75, corner7_v=-6.58,
    corner8_u=7.65, corner8_v=-18.53,
    hole1_u=-0.15, hole1_v=-12.68, hole1_diameter=6.03,
    hole2_u=-0.05, hole2_v=5.98, hole2_diameter=10.04,
):
    part = cq.Workplane("XY").polyline([(corner1_u, corner1_v), (corner2_u, corner2_v), (corner3_u, corner3_v), (corner4_u, corner4_v), (corner5_u, corner5_v), (corner6_u, corner6_v), (corner7_u, corner7_v), (corner8_u, corner8_v)]).close().extrude(thickness)
    part = part.cut(cq.Workplane("XY", origin=(hole1_u, hole1_v, -1)).circle(hole1_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole2_u, hole2_v, -1)).circle(hole2_diameter / 2).extrude(thickness + 2))
    return part
